package me.summariseme.app;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.media.MediaRecorder;import android.os.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class RecordingService extends Service {
 public static final String CHANNEL="recording";private static MediaRecorder recorder;private static boolean paused=false;private static long elapsed=0,segment=0;private static String currentId="",metadata="",error="";private PowerManager.WakeLock wake;private final Handler handler=new Handler(Looper.getMainLooper());
 public static File directory(Context c){File d=new File(c.getFilesDir(),"recordings");d.mkdirs();return d;}
 public static synchronized void setError(String e){error=e;}
 private static long millis(){return elapsed+(recorder!=null&&!paused?SystemClock.elapsedRealtime()-segment:0);}
 public static synchronized String snapshot(Context c){JSONObject j=new JSONObject();try{j.put("active",recorder!=null);j.put("paused",paused);j.put("seconds",millis()/1000.0);j.put("error",error);int max=0;if(recorder!=null&&!paused)try{max=recorder.getMaxAmplitude();}catch(Exception ignored){}j.put("level",Math.min(1,max/12000.0));File[] files=directory(c).listFiles((d,n)->n.endsWith(".json"));if(files!=null&&files.length>0){java.util.Arrays.sort(files,java.util.Comparator.comparingLong(File::lastModified));j.put("completed",new JSONObject(new String(java.nio.file.Files.readAllBytes(files[0].toPath()),StandardCharsets.UTF_8)));}}catch(Exception ignored){}return j.toString();}
 @Override public void onCreate(){super.onCreate();NotificationChannel channel=new NotificationChannel(CHANNEL,"Voice recording",NotificationManager.IMPORTANCE_LOW);channel.setDescription("Recording controls while using other apps or the lock screen");getSystemService(NotificationManager.class).createNotificationChannel(channel);}
 private PendingIntent action(String action){Intent i=new Intent(this,RecordingService.class).setAction(action);return PendingIntent.getService(this,action.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(){Intent open=new Intent(this,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);Notification.Builder b=new Notification.Builder(this,CHANNEL).setSmallIcon(R.drawable.ic_mic).setContentTitle(paused?"Recording paused":"Recording voice note").setContentText(paused?"Resume or finish your voice note":"Microphone active · tap to return").setContentIntent(PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_SERVICE).setVisibility(Notification.VISIBILITY_PRIVATE).addAction(new Notification.Action.Builder(null,paused?"Resume":"Pause",action(paused?"resume":"pause")).build()).addAction(new Notification.Action.Builder(null,"Finish",action("finish")).build());if(!paused)b.setWhen(System.currentTimeMillis()-millis()).setUsesChronometer(true);return b.build();}
 private void refresh(){if(recorder!=null)getSystemService(NotificationManager.class).notify(1,notification());}
 @Override public int onStartCommand(Intent intent,int flags,int startId){synchronized(RecordingService.class){String action=intent==null?"":intent.getAction();try{if("begin".equals(action)){if(recorder!=null)return START_NOT_STICKY;error="";metadata=intent.getStringExtra("metadata");currentId=java.util.UUID.randomUUID().toString();elapsed=0;paused=false;if(Build.VERSION.SDK_INT>=29)startForeground(1,notification(),ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE);else startForeground(1,notification());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioEncodingBitRate(64000);recorder.setAudioSamplingRate(44100);recorder.setOutputFile(new File(directory(this),currentId+".m4a").getAbsolutePath());recorder.setOnErrorListener((mr,what,extra)->{synchronized(RecordingService.class){error="Microphone interrupted. Return to the app to check the recording.";finish(true);}});recorder.prepare();recorder.start();segment=SystemClock.elapsedRealtime();wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"SummariseMe:Recording");wake.acquire(6*60*60*1000L);refresh();handler.post(tick);}else if("pause".equals(action)&&recorder!=null&&!paused){elapsed=millis();recorder.pause();paused=true;refresh();}else if("resume".equals(action)&&recorder!=null&&paused){recorder.resume();segment=SystemClock.elapsedRealtime();paused=false;refresh();}else if("finish".equals(action)){finish(true);}else if("cancel".equals(action)){finish(false);}}catch(Exception e){error="Unable to record: "+e.getClass().getSimpleName();finish(false);}}return START_NOT_STICKY;}
 private final Runnable tick=new Runnable(){public void run(){synchronized(RecordingService.class){if(recorder!=null){refresh();handler.postDelayed(this,1000);}}}};
 private void finish(boolean save){handler.removeCallbacks(tick);long seconds=Math.max(0,millis());boolean valid=recorder!=null;try{if(recorder!=null)recorder.stop();}catch(Exception e){valid=false;error="The recording was too short or interrupted.";}finally{if(recorder!=null)recorder.release();recorder=null;}if(wake!=null&&wake.isHeld())wake.release();File file=new File(directory(this),currentId+".m4a");if(save&&valid&&file.length()>0){try{JSONObject done=new JSONObject().put("id",currentId).put("seconds",seconds/1000.0).put("metadata",metadata==null?"{}":metadata);java.nio.file.Files.write(new File(directory(this),currentId+".json").toPath(),done.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){error="Audio saved, but recovery details could not be written.";}}else file.delete();paused=false;elapsed=0;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onDestroy(){synchronized(RecordingService.class){if(recorder!=null)finish(true);}super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
